         !$omp end parallel
      end block
      call gemv(state%s14, tmp4701, tmp35903, trans="t")
      tmp35904 = tmp35464 + tmp35903
      tmp35905 = tmp35904 + tmp28080
      tmp35906 = tmp35905*state%v
      tmp35907 = state%s31*dv
      tmp35908 = tmp35906 + tmp35907
      tmp35909 = tmp15237*state%s34
      tmp35910 = state%s38*tmp15242
      tmp35911 = tmp35909 + tmp35910
      tmp35912 = tmp28080*state%s32
      tmp35913 = state%s30*tmp15247
      tmp35914 = tmp35912 + tmp35913
      tmp35915 = tmp35911 + tmp35914
      hvp_a = tmp35908 + tmp35915
      tmp35916 = 0.5_wp*tmp13792
      tmp35917 = tmp35916 + tmp4700
      tmp35918 = tmp35917 + tmp15252
      tmp35919 = tmp35905*state%a
      tmp35920 = state%s31*da
      tmp35921 = tmp35919 + tmp35920
      hvp_v = tmp35918 + tmp35921
   end subroutine lpb_tangent_one

   module subroutine lpb_response(state, dv, hvp_v, error)
      !> State of lpb
      type(lpb_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call lpb_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[lpb_response] call lpb_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call lpb_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine lpb_response

   !> One direction of lpb_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_response_one(state, dv, hvp_v, error)
      !> State of lpb
      type(lpb_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:), tmp13(:), tmp14(:), &
                               tmp15(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), &
                               tmp21(:), tmp22(:), tmp23(:), tmp24(:), tmp25(:), tmp26(:), &
                               tmp27(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[lpb_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[lpb_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%op2%points => state%r
      state%op2%a => state%a
      state%op2%c2 => state%s7
      state%op2%c3 => state%s12
      state%op2%c5 => state%s13
      state%op2%c6 => state%s14
      tmp1 = state%a*dv
      call gemv(state%s12, tmp1, tmp2)
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = dv + tmp3
      tmp5 = state%s15*tmp4
      call gemv(state%s14, tmp1, tmp6)
      tmp7 = (-0.15915494309189535_wp)*tmp6
      tmp8 = dv + tmp7
      tmp9 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp8, tmp9, error)
      if (allocated(error)) return
      call gemv(state%s13, tmp9, tmp10)
      tmp11 = state%s2*tmp10
      tmp12 = tmp5 + tmp11
      tmp13 = 0.0_wp
      call state%solver%solve(state%op2, .false., tmp12, tmp13, error)
      if (allocated(error)) return
      tmp14 = 0.5_wp*tmp13
      tmp15 = 0.0_wp
      call state%solver%solve(state%op2, .true., dv, tmp15, error)
      if (allocated(error)) return
      tmp16 = state%s21*tmp15
      call gemv(state%s13, tmp16, tmp17, trans="t")
      tmp18 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp17, tmp18, error)
      if (allocated(error)) return
      tmp19 = tmp14 + tmp18
      tmp20 = state%s25*tmp15
      tmp21 = tmp19 + tmp20
      tmp22 = (-0.15915494309189535_wp)*tmp18
      call gemv(state%s14, tmp22, tmp23, trans="t")
      tmp24 = state%s28*tmp15
      call gemv(state%s12, tmp24, tmp25, trans="t")
      tmp26 = tmp23 + tmp25
      tmp27 = tmp26*state%a
      hvp_v = tmp21 + tmp27
   end subroutine lpb_response_one

end submodule pcmgen_gauss_lpb_tangent
